INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63269986', 63269986, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individual Penyusunan Kebijakan Pertanahan Dalam Pengelolaan Ruang Dalam Bumi Kegiatan Penyusunan Rekomendasi Kebijakan Penataan Ruang Dalam Bumi Direktorat Tata Ruang, Perkotaan, Pertanahan, Dan Penanggulangan Bencana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 140000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Menyusun kerangka kerja kegiatan, termasuk instrumen, jadwal, dan mekanisme pelaksanaan kajian ruang bawah bumi. 2. Menginventarisasi dan mengidentifikasi isu strategis, potensi, tantangan aspek pertanahan dalam pemanfaatan ruang dalam bumi. 3. Melakukan kajian literatur untuk mendapatkan gambaran kondisi ideal kebijakan pertanahan dalam pengelolaan ruang bawah bumi baik ditingkat nasional maupun internasional. 4. Melakukan analisis regulasi dan kebijakan pertanahan terkait pemanfaatan ruang dalam bumi khususnya terkait hak, batasan dan kewajiban atas ruang dalam bumi dan kaitannya dengan mekanisme KKPR.', 'Dalam rangka mendukung kegiatan ini, maka dibutuhkan 1 (satu) orang Jasa Konsultan Individual Analisis Kebijakan Pertanahan dalam Pengelolaan Ruang Dalam Bumi. Adapun kualifikasi yang diperlukan adalah Pendidikan Minimal Strata-2 (S2) bidang Pengembangan Wilayah/Hukum dengan pengalaman sekurang–kurangnya 10 tahun dibidangnya. Tugas utamanya adalah membantu melakukan analisis data dan menyusun rekomendasi kebijakan pemanfaatan ruang bawah bumi di dalam aspek hukum pertanahan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 843562);
