INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63322803', 63322803, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR KEKARANTINAAN KESEHATAN SOEKARNO HATTA', 'Pelatihan Dasar-Dasar AMDAL (Online Class)', 'Jasa Lainnya', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 8200000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '2 orang', '1. Belanja Jasa Lainnya; paket pelatihan untuk 2 orang Analisis Mengenai Dampak Lingkungan (AMDAL) sangat penting untuk memastikan bahwa setiap kegiatan yang berpotensi menimbulkan dampak lingkungan dapat diidentifikasi, dinilai, dan dikelola dengan baik. Pengawasan lingkungan berfungsi untuk memastikan bahwa setiap kegiatan di bandara—baik itu pembangunan, pengoperasian, maupun pengelolaan dampak lingkungan—berjalan sesuai dengan rencana yang telah disusun dalam AMDAL, Tanpa pengawasan yang efektif, dampak lingkungan dari kegiatan bandara bisa meningkat dan menimbulkan masalah jangka panjang. Untuk itu diperlukan ketersediaan sumber daya manusia yang mumpuni dengan kompetensi melalui kemampuan untuk menganalisis kondisi riil di lapangan maupun melalui Rencana Pengelolaan Lingkungan (RKL) dan Rencana Pemantauan lingkungan (RPL) bandar udara yang rutin dilaporkan setiap 6 bulan melalui suatu Analisis Risiko Kesehatan Lingkungan maupun Analisis Dampak Kesehatan Lingkungan. Pelatihan ini direncanakan dengan mengikutkan tenaga pengendalian faktor risiko lingkungan berjumlah 2 orang dengan agenda yang diselenggarakan oleh Pusat Penelitian Sumber Daya Manusia dan Lingkungan Universitas Indonesia dengan sistem daring', 'Paket pelatihan Dasar-Dasar AMDAL (Online Class) yang diselenggarakan oleh Pusat Penelitian Sumber Daya Manusia dan Lingkungan Universitas Indonesia sebanyak 2 orang', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 848965);
